/// Decodes bytes of a single-byte OEM code page; every byte value is valid.
pub fn decode(buf: &[u8], high: &[char; 128]) -> String {
    buf.iter().map(|&b| if b < 0x80 { b as char } else { high[(b - 0x80) as usize] }).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cp850_decodes_portuguese_text() {
        // "Ação São Paulo" in CP850
        let bytes = [0x41, 0x87, 0xc6, 0x6f, 0x20, 0x53, 0xc6, 0x6f, 0x20, 0x50, 0x61, 0x75, 0x6c, 0x6f];
        assert_eq!(decode(&bytes, &CP850), "Ação São Paulo");
        assert_eq!(decode(&[0x82, 0xa0, 0xa1, 0xa2, 0xa3, 0x90, 0x8a], &CP850), "éáíóúÉè");
    }

    #[test]
    fn cp437_box_and_accents() {
        assert_eq!(decode(&[0x80, 0x81, 0xc9, 0xcd, 0xbb], &CP437), "Çü╔═╗");
    }
}
